from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        # If already all zeros, no queries needed.
        if all(x == 0 for x in nums):
            return 0

        # dp[j] is a bitset: bit s is 1 iff sum s is achievable for index j
        dp = [1] * n          # bit 0 is set (sum 0 achievable with no queries)
        achieved = [x == 0 for x in nums]

        for i, (l, r, val) in enumerate(queries):
            for j in range(l, r + 1):
                if not achieved[j]:
                    # Add option to use this query for index j
                    dp[j] |= (dp[j] << val)
                    # Keep only sums up to nums[j] (higher sums can never decrease)
                    mask = (1 << (nums[j] + 1)) - 1
                    dp[j] &= mask

                    if (dp[j] >> nums[j]) & 1:
                        achieved[j] = True

            if all(achieved):
                return i + 1

        return -1
