from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        # Build a segment tree over basket capacities.
        size = 1
        while size < n:
            size <<= 1
        tree = [0] * (2 * size)
        for i in range(n):
            tree[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])

        unplaced = 0

        for f in fruits:
            # If even the maximum available capacity is less than f, it cannot be placed.
            if tree[1] < f:
                unplaced += 1
                continue

            # Find the leftmost basket with capacity >= f.
            node = 1
            while node < size:
                if tree[2 * node] >= f:
                    node = 2 * node
                else:
                    node = 2 * node + 1
            idx = node - size

            # Mark this basket as used (capacity becomes 0).
            tree[node] = 0
            node //= 2
            while node:
                tree[node] = max(tree[2 * node], tree[2 * node + 1])
                node //= 2

        return unplaced
