class Solution:
    def maxSum(self, nums: List[int]) -> int:
        # Collect all distinct positive numbers
        positives = set()
        max_val = float('-inf')
        for x in nums:
            if x > 0:
                positives.add(x)
            if x > max_val:
                max_val = x

        # If there is at least one positive number, we can keep exactly one
        # occurrence of each positive number (deleting everything else) and
        # take the whole remaining array as the subarray. Their sum is maximal.
        if positives:
            return sum(positives)

        # Otherwise all numbers are <= 0; we must pick at least one element.
        # The best we can do is pick the maximum element (closest to zero).
        return max_val
